"use client";

import { useMemo, useState, type ReactNode } from "react";

export type DataTableColumn<Row> = { key: keyof Row; header: string; cell?: (row: Row) => ReactNode };
export function DataTable<Row extends Record<string, unknown>>({ rows, columns, caption = "Data table" }: { rows: Row[]; columns: DataTableColumn<Row>[]; caption?: string }) { const [sort, setSort] = useState<keyof Row | null>(null); const [ascending, setAscending] = useState(true); const sorted = useMemo(() => sort ? [...rows].sort((a, b) => String(a[sort]).localeCompare(String(b[sort])) * (ascending ? 1 : -1)) : rows, [ascending, rows, sort]); return <div className="co-w-full co-overflow-auto"><table className="co-w-full co-text-sm"><caption className="co-sr-only">{caption}</caption><thead className="co-border-b"><tr>{columns.map((column) => <th scope="col" className="co-p-3 co-text-left"><button type="button" className="co-font-medium focus-visible:co-ring-2" onClick={() => { setAscending(sort === column.key ? !ascending : true); setSort(column.key); }}>{column.header}{sort === column.key ? (ascending ? " ↑" : " ↓") : ""}</button></th>)}</tr></thead><tbody>{sorted.map((row, rowIndex) => <tr className="co-border-b hover:co-bg-black/5" key={rowIndex}>{columns.map((column) => <td className="co-p-3" key={String(column.key)}>{column.cell ? column.cell(row) : String(row[column.key] ?? "")}</td>)}</tr>)}</tbody></table></div>; }
